#include <iostream>
#include <memory>
#include <utility>

struct Request {
    int id = 7;

    ~Request() {
        std::cout << "销毁请求\n";
    }
};

int main() {
    auto req = std::make_shared<Request>();
    std::cout << "初始计数 " << req.use_count() << "\n";

    {
        auto backup = req;
        std::cout << "共同拥有 " << req.use_count() << "\n";
    } // A

    std::cout << "离开内层 " << req.use_count() << "\n";
} // B
